prologue:
/* Camera state snapshot helpers */
static MOD_UNUSED int cam_read(AmodCamera* out) {
    if (API->camera == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->camera->Get(SELF, out);
}

static MOD_UNUSED float cam_vec(int which, int axis) {
    AmodCamera c;
    if (axis < 0 || axis > 2 || cam_read(&c) == 0) return 0.0f;
    if (which == 0) return c.eye[axis];
    if (which == 1) return c.target[axis];
    if (which == 2) return c.up[axis];
    return c.followed[axis];
}

static MOD_UNUSED float cam_roll(void) {
    AmodCamera c;
    return cam_read(&c) != 0 ? c.roll : 0.0f;
}

static MOD_UNUSED int cam_flag(int which) {
    AmodCamera c;
    if (cam_read(&c) == 0) return 0;
    if (which == 0) return c.isShaking != 0;
    if (which == 1) return c.followsEye != 0;
    return c.followsTarget != 0;
}

static MOD_UNUSED float cam_focus(int axis) {
    float pt[3] = { 0.0f, 0.0f, 0.0f };
    if (axis < 0 || axis > 2 || API->camera == 0) return 0.0f;
    return API->camera->GetFocus(SELF, pt) != 0 ? pt[axis] : 0.0f;
}

static MOD_UNUSED void cam_set_eye(float x, float y, float z) {
    float p[3];
    p[0] = x; p[1] = y; p[2] = z;
    if (API->camera != 0) API->camera->SetEye(SELF, p);
}

static MOD_UNUSED void cam_set_target(float x, float y, float z) {
    float p[3];
    p[0] = x; p[1] = y; p[2] = z;
    if (API->camera != 0) API->camera->SetTarget(SELF, p);
}

static MOD_UNUSED void cam_set_up(float x, float y, float z) {
    float p[3];
    p[0] = x; p[1] = y; p[2] = z;
    if (API->camera != 0) API->camera->SetUp(SELF, p);
}

static MOD_UNUSED void cam_follow(float x, float y, float z) {
    float p[3];
    p[0] = x; p[1] = y; p[2] = z;
    if (API->camera != 0) API->camera->Follow(SELF, p);
}

static MOD_UNUSED void cam_place(float x, float y, float z) {
    float p[3];
    p[0] = x; p[1] = y; p[2] = z;
    if (API->camera != 0) API->camera->Place(SELF, p);
}

/* scripts/camera.txt properties: 13 floats + rock_count (int) */
static MOD_UNUSED float cam_prop(const char* key) {
    AmodValue v;
    if (API->camera == 0 || key == 0) return 0.0f;
    memset(&v, 0, sizeof v);
    if (API->camera->GetProperty(SELF, key, &v) == 0) return 0.0f;
    if (v.kind == AMOD_VALUE_INT || v.kind == AMOD_VALUE_BOOL) return (float)v.integer;
    if (v.kind == AMOD_VALUE_FLOAT && v.count > 0) return v.numbers[0];
    return 0.0f;
}

static MOD_UNUSED void cam_set_prop(const char* key, float number) {
    AmodValue cur, v;
    if (API->camera == 0 || key == 0) return;
    memset(&cur, 0, sizeof cur);
    memset(&v, 0, sizeof v);
    if (API->camera->GetProperty(SELF, key, &cur) != 0 && cur.kind == AMOD_VALUE_INT) {
        v.kind = AMOD_VALUE_INT;
        v.integer = (int)number;
    } else {
        v.kind = AMOD_VALUE_FLOAT;
        v.count = 1;
        v.numbers[0] = number;
    }
    API->camera->SetProperty(SELF, key, &v);
}

static MOD_UNUSED const char* cam_prop_name(int at) {
    const char* name = API->camera != 0 ? API->camera->PropertyNameAt(SELF, at) : 0;
    return name != 0 ? name : "";
}

/* Last rendered view and in-place view handler editor */
static MOD_UNUSED float cam_view(int which, int axis) {
    AmodCameraView v;
    if (axis < 0 || axis > 2 || API->camera == 0) return 0.0f;
    memset(&v, 0, sizeof v);
    v.structSize = sizeof v;
    if (API->camera->GetView(SELF, &v) == 0) return 0.0f;
    if (which == 0) return v.eye[axis];
    if (which == 1) return v.target[axis];
    return v.up[axis];
}

static MOD_UNUSED void cam_view_set(AmodCameraView* view, int which, float x, float y, float z) {
    float* dst;
    if (view == 0) return;
    dst = which == 0 ? view->eye : (which == 1 ? view->target : view->up);
    dst[0] = x; dst[1] = y; dst[2] = z;
}

/* World projection lens */
static MOD_UNUSED float cam_lens(int which) {
    AmodCameraLens l;
    if (API->camera == 0) return 0.0f;
    memset(&l, 0, sizeof l);
    l.structSize = sizeof l;
    if (API->camera->GetLens(SELF, &l) == 0) return 0.0f;
    if (which == 0) return l.fov;
    if (which == 1) return l.aspect;
    if (which == 2) return l.nearPlane;
    return l.farPlane;
}

static MOD_UNUSED void cam_set_lens(float fov, float aspect, float nearPlane, float farPlane) {
    AmodCameraLens l;
    if (API->camera == 0) return;
    memset(&l, 0, sizeof l);
    l.structSize = sizeof l;
    l.fov = fov;
    l.aspect = aspect;
    l.nearPlane = nearPlane;
    l.farPlane = farPlane;
    API->camera->SetLens(SELF, &l);
}
